PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS activity_data(id INTEGER PRIMARY KEY AUTOINCREMENT,period TEXT NOT NULL,site TEXT NOT NULL,source TEXT NOT NULL,scope TEXT NOT NULL,metric TEXT NOT NULL,activity REAL NOT NULL,unit TEXT NOT NULL,factor_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS emission_factors(factor_id TEXT PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL,factor REAL NOT NULL,source TEXT NOT NULL,version TEXT NOT NULL,scope TEXT NOT NULL,effective_from TEXT,effective_to TEXT,is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scenarios(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,scope2_reduction_pct REAL NOT NULL DEFAULT 0,payload_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS actions(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,owner TEXT,impact TEXT,status TEXT,capex REAL,annual_saving REAL,annual_reduction_tco2e REAL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,event_type TEXT NOT NULL,entity_type TEXT,entity_id TEXT,payload_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
